using System;using System.IO;using System.Drawing;using System.Windows.Forms;
namespace EanEtikety {
public sealed class UpdatesDialog:Form {
 readonly UpdateActivation service;readonly string running;readonly Action<Control> style;readonly Label information=new Label();readonly ModernButton download=new ModernButton(),activate=new ModernButton(),rollback=new ModernButton();UpdateOffer offer;string prepared;
 Func<UpdateNetwork> networkFactory=()=>new UpdateNetwork();Func<string,bool> confirm;
 [System.ComponentModel.DesignerSerializationVisibility(System.ComponentModel.DesignerSerializationVisibility.Hidden)]public string RequestedDirectory{get;private set;}[System.ComponentModel.DesignerSerializationVisibility(System.ComponentModel.DesignerSerializationVisibility.Hidden)]public bool RollbackRequested{get;private set;}
 public UpdatesDialog(UpdateActivation service,string runningDirectory,Action<Control> style){this.service=service;running=runningDirectory;this.style=style??delegate{};Text=Loc.T("Aktualizácie");Font=UiFonts.Get(10.5f);Size=new Size(700,570);MinimumSize=new Size(520,400);StartPosition=FormStartPosition.CenterParent;AutoScaleMode=AutoScaleMode.Dpi;ShowInTaskbar=false;
  confirm=message=>UiMessageBox.Show(this,message,Loc.T("Aktualizácie"),MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes;
  var scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(16)};Controls.Add(scroll);var fields=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1};fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));scroll.Controls.Add(fields);
  Add(fields,new Label{Text=Loc.T("Kontrola internetu sa spustí iba na vyžiadanie. Rozpracované projekty, profily a kalibrácie zostanú zachované."),AutoSize=true,MaximumSize=new Size(620,0)});information.AutoSize=true;information.MaximumSize=new Size(620,0);information.UseMnemonic=false;information.AccessibleName=Loc.T("Stav aktualizácie");Add(fields,information);
  var check=Button("Skontrolovať aktualizácie",CheckOnline);Add(fields,check);download.Text=Loc.T("Stiahnuť a pripraviť");download.Height=42;download.Enabled=false;download.Click+=delegate{Download();};Add(fields,download);Add(fields,Button("Použiť ručne stiahnutý ZIP…",Import));
  activate.Text=Loc.T("Spustiť pripravenú verziu…");activate.Height=42;activate.Enabled=false;activate.Click+=delegate{RequestActivation();};Add(fields,activate);
  rollback.Text=Loc.T("Návrat na predchádzajúcu verziu…");rollback.Height=42;rollback.Enabled=false;rollback.Click+=delegate{RequestRollback();};Add(fields,rollback);
  Add(fields,new Label{Text=Loc.T("Nová verzia sa pripraví samostatne. Pred spustením sa vytvorí záloha nastavení; pôvodné súbory zostanú na mieste."),AutoSize=true,MaximumSize=new Size(620,0)});var close=Button("Zavrieť",()=>Close());Add(fields,close);CancelButton=close;
  try{var p=UpdatePackage.Read(Path.Combine(running,"package-manifest.xml"));information.Text=Loc.T("Nainštalovaná zostava")+": "+p.PackageId.Substring(0,12)+" / "+p.Family;}catch{information.Text=Loc.T("Vývojová alebo staršia inštalácia bez identifikácie balíka.");}
  try{var state=service.State();rollback.Enabled=state.Previous!=null&&state.AuthorizedRoots.Exists(r=>UpdateActivation.SamePath(r,running));if(state.Current!=null&&!UpdateActivation.SamePath(state.Current.Directory,running)){prepared=state.Current.Directory;activate.Enabled=true;}}catch(Exception ex){information.Text=ex.Message;}
  fields.SizeChanged+=delegate{foreach(Control c in fields.Controls)if(c is Label)c.MaximumSize=new Size(Math.Max(200,fields.Width-8),0);};this.style(this);
 }
 static void Add(TableLayoutPanel p,Control c){c.Dock=DockStyle.Top;c.TabIndex=p.Controls.Count;c.Margin=new Padding(0,5,0,9);p.Controls.Add(c,0,p.RowCount++);p.RowStyles.Add(new RowStyle(SizeType.AutoSize));}
 static ModernButton Button(string text,Action action){var b=new ModernButton{Text=Loc.T(text),Height=42};b.Click+=delegate{action();};return b;}
 bool Work<T>(string title,Func<T> work,out T result){return WorkDialog.Run(this,"update",Loc.T(title),Font,Icon,style,work,out result);}
 void CheckOnline(){try{UpdateOffer found;if(!Work("Kontrolujem aktualizácie…",()=>{using(var client=networkFactory())return client.Check(service.Family);},out found))return;prepared=null;activate.Enabled=false;offer=found;download.Enabled=true;try{var current=UpdatePackage.Read(Path.Combine(running,"package-manifest.xml"));if(current.PackageId==offer.PackageId){information.Text=Loc.T("Používate aktuálnu zostavu.");download.Enabled=false;offer=null;return;}}catch{}information.Text=Loc.T("Dostupná nová zostava")+": "+found.PackageId.Substring(0,12)+" / "+found.Family;}catch(Exception ex){information.Text=Loc.T("Aktualizáciu sa nepodarilo overiť. Program môžete ďalej používať bez internetu.")+"\r\n"+ex.Message;offer=null;download.Enabled=false;}}
 void Download(){var selected=offer;if(selected==null)return;try{string path;if(!Work("Pripravujem aktualizáciu…",()=>{using(var client=networkFactory()){string zip=client.Download(selected,Path.Combine(service.Root,"downloads"));try{return UpdatePreparation.Prepare(zip,selected.Sha256,service.Family,service.PackagesRoot,selected);}finally{if(File.Exists(zip))File.Delete(zip);}}},out path))return;Ready(path);}catch(Exception ex){information.Text=ex.Message;}}
 void Import(){using(var zip=new OpenFileDialog{Filter="ZIP|*.zip"}){if(zip.ShowDialog(this)!=DialogResult.OK)return;using(var sum=new OpenFileDialog{Filter="SHA256SUMS|*.txt",InitialDirectory=Path.GetDirectoryName(zip.FileName)}){if(sum.ShowDialog(this)!=DialogResult.OK)return;bool consent=confirm(Loc.T("Použiť tento ZIP z dôveryhodného zdroja? Kontrolný súčet overí integritu, nie nezávislý podpis vydavateľa."));if(consent)PrepareLocal(zip.FileName,sum.FileName,true);}}}
 public bool PrepareLocal(string zip,string checksum,bool sourceConfirmed){if(!sourceConfirmed)return false;try{string path;if(!Work("Overujem aktualizáciu…",()=>UpdatePreparation.Prepare(zip,UpdatePreparation.ReadChecksum(checksum,Path.GetFileName(zip)),service.Family,service.PackagesRoot),out path))return false;Ready(path);return true;}catch(Exception ex){information.Text=ex.Message;return false;}}
 void Ready(string path){var candidate=UpdatePackage.Read(Path.Combine(path,"package-manifest.xml"));try{var current=UpdatePackage.Read(Path.Combine(running,"package-manifest.xml"));if(current.PackageId==candidate.PackageId){prepared=null;activate.Enabled=false;information.Text=Loc.T("Používate aktuálnu zostavu.");return;}}catch{}prepared=path;activate.Enabled=true;information.Text=Loc.T("Balík je overený a pripravený. Spustenie vyžaduje vaše potvrdenie.");}
 void RequestActivation(){if(prepared==null||!confirm(Loc.T("Spustiť novú verziu a zavrieť toto okno programu? Neuložený dokument môžete uložiť alebo aktualizáciu zrušiť.")))return;RequestedDirectory=prepared;RollbackRequested=false;DialogResult=DialogResult.OK;Close();}
 void RequestRollback(){if(!rollback.Enabled||!confirm(Loc.T("Vrátiť sa na predchádzajúcu verziu? Súčasné nastavenia zostanú zachované.")))return;RollbackRequested=true;DialogResult=DialogResult.OK;Close();}
}
public partial class MainForm {
 Func<UpdateActivation> updateActivationFactory=UpdateActivation.Default;Func<string,bool> updateLauncher=UpdateActivation.Launch;string updateRunningDirectory=AppDomain.CurrentDomain.BaseDirectory;
 void ShowUpdates(){var service=updateActivationFactory();using(var dialog=new UpdatesDialog(service,updateRunningDirectory,ApplyColors))if(dialog.ShowDialog(this)==DialogResult.OK)CompleteUpdateSwitch(service,dialog.RequestedDirectory,dialog.RollbackRequested);}
 void CompleteUpdateSwitch(UpdateActivation service,string target,bool rollback){FormClosingEventHandler handler=delegate(object sender,FormClosingEventArgs e){if(e.Cancel)return;try{if(rollback)service.Rollback(updateRunningDirectory,updateLauncher);else service.Activate(updateRunningDirectory,target,updateLauncher);}catch(Exception ex){e.Cancel=true;Error(ex);}};FormClosing+=handler;try{Close();}finally{FormClosing-=handler;}}
}
}
